/// <summary>Detached XAnim authoring state.  The snapshot includes every
/// packed stream and delta frame payload, never loader pointer cells.</summary>
public sealed class XAnimAuthoredSnapshot : ITargetZoneDetachedSemanticSnapshot
{
    internal XAnimAuthoredSnapshot(XAnimBuildData data) => Data = data.Copy();
    internal XAnimBuildData Data { get; }
    public XAssetType AssetType => XAssetType.XAnim;
    internal static XAnimAuthoredSnapshot Import(TargetZoneRowSource source) => source.AuthoredDefinition?.SemanticSnapshot is XAnimAuthoredSnapshot snapshot
        ? snapshot : throw new InvalidDataException("XAnim editing requires a capture-time detached semantic snapshot because nested data pointers may be aliases.");
    internal static XAnimAuthoredSnapshot FromLoaded(XAnimPartsAsset asset) => new(new XAnimBuildData(asset.Name, asset.DataByteCount, asset.DataShortCount, asset.DataIntCount, asset.RandomDataByteCount, asset.RandomDataIntCount, asset.NumFrames, asset.Flags, asset.DeltaFlags, asset.BoneCounts, asset.BoneNameCount, asset.NotifyCount, asset.AssetType, asset.Pad1F, asset.RandomDataShortCount, asset.IndexCount, asset.Framerate, asset.Frequency, asset.Names, asset.PackedDataStreams.QuantizedBytes, asset.PackedDataStreams.QuantizedShorts, asset.PackedDataStreams.QuantizedInts, asset.PackedDataStreams.RandomizedQuantizedShorts, asset.PackedDataStreams.RandomizedQuantizedBytes, asset.PackedDataStreams.RandomizedQuantizedInts, asset.Indices.FrameIndices, asset.Notify.Select(value => new XAnimNotifyBuildData(value.Name, value.Time)), Delta(asset.DeltaPart)));
    private static XAnimDeltaBuildData? Delta(XAnimDeltaPart? value) => value is null ? null : new(Trans(value.Trans), Quat2(value.Quat2), Quat(value.Quat));
    private static XAnimPartTransBuildData? Trans(XAnimPartTrans? value) { if (value is null) return null; if (value.Size == 0) return new(value.Size, value.SmallTrans, value.Pad3, value.Frame0 is { } frame ? Vector(frame.X, frame.Y, frame.Z) : null, null); XAnimPartTransFrames frames = value.Frames ?? throw new InvalidDataException("Dynamic XAnim translation lacks its frame data."); return new(value.Size, value.SmallTrans, value.Pad3, null, new XAnimTransFramesBuildData(Vector(frames.Mins.X, frames.Mins.Y, frames.Mins.Z), Vector(frames.Size.X, frames.Size.Y, frames.Size.Z), frames.DynamicFrames.FrameIndices, frames.FramePayload is SmallXAnimTransFramePayload small ? small.Frames.Select(entry => new XAnimSmallTransFrameBuildData(entry.X, entry.Y, entry.Z)).ToArray() : null, frames.FramePayload is LargeXAnimTransFramePayload large ? large.Frames.Select(entry => new XAnimLargeTransFrameBuildData(entry.X, entry.Y, entry.Z)).ToArray() : null)); }
    private static XAnimQuat2PartBuildData? Quat2(XAnimDeltaPartQuat2? value) => value is null ? null : value.Size == 0 ? new(value.Size, value.Pad2, value.Pad3, value.Frame0 is { } frame ? new XAnimQuat2BuildData(frame.Value0, frame.Value1) : null, null) : new(value.Size, value.Pad2, value.Pad3, null, new XAnimQuat2FramesBuildData(value.Frames!.DynamicFrames.FrameIndices, value.Frames.Frames.Select(entry => new XAnimQuat2BuildData(entry.Value0, entry.Value1)).ToArray()));
    private static XAnimQuatPartBuildData? Quat(XAnimDeltaPartQuat? value) => value is null ? null : value.Size == 0 ? new(value.Size, value.Pad2, value.Pad3, value.Frame0 is { } frame ? new XAnimQuatBuildData(frame.Value0, frame.Value1, frame.Value2, frame.Value3) : null, null) : new(value.Size, value.Pad2, value.Pad3, null, new XAnimQuatFramesBuildData(value.Frames!.DynamicFrames.FrameIndices, value.Frames.Frames.Select(entry => new XAnimQuatBuildData(entry.Value0, entry.Value1, entry.Value2, entry.Value3)).ToArray()));
    private static Float3BuildData Vector(float x, float y, float z) => new(x, y, z);
}

public sealed class XAnimBuildData : IXAnimBuildData
