    internal XAnimBuildData Copy() => new(Name, DataByteCount, DataShortCount, DataIntCount, RandomDataByteCount, RandomDataIntCount, NumFrames, Flags, DeltaFlags, _boneCounts, BoneNameCount, NotifyCount, AssetTypeValue, Pad1F, RandomDataShortCount, IndexCount, Framerate, Frequency, _names, _dataBytes, _dataShorts, _dataInts, _randomDataShorts, _randomDataBytes, _randomDataInts, _indices, _notify, Delta);
