}

public sealed class XAnimDraft
{
    private XAnimBuildData _data; internal XAnimDraft(XAnimBuildData data) => _data = data.Copy(); public XAnimBuildData Data => _data.Copy();
    public void SetRates(float framerate, float frequency) => _data = Replace(framerate: framerate, frequency: frequency);
    public void ReplaceDelta(XAnimDeltaBuildData? delta) => _data = Replace(delta: delta, replaceDelta: true);
    public void ReplaceStreams(IEnumerable<byte> dataBytes, IEnumerable<short> dataShorts, IEnumerable<int> dataInts, IEnumerable<short> randomDataShorts, IEnumerable<byte> randomDataBytes, IEnumerable<int> randomDataInts, IEnumerable<ushort> indices) { ArgumentNullException.ThrowIfNull(dataBytes); ArgumentNullException.ThrowIfNull(dataShorts); ArgumentNullException.ThrowIfNull(dataInts); ArgumentNullException.ThrowIfNull(randomDataShorts); ArgumentNullException.ThrowIfNull(randomDataBytes); ArgumentNullException.ThrowIfNull(randomDataInts); ArgumentNullException.ThrowIfNull(indices); _data = Replace(dataBytes: dataBytes, dataShorts: dataShorts, dataInts: dataInts, randomDataShorts: randomDataShorts, randomDataBytes: randomDataBytes, randomDataInts: randomDataInts, indices: indices, countsFromStreams: true); }
    internal XAnimDraft Clone() => new(_data);
    private XAnimBuildData Replace(float? framerate = null, float? frequency = null, XAnimDeltaBuildData? delta = null, IEnumerable<byte>? dataBytes = null, IEnumerable<short>? dataShorts = null, IEnumerable<int>? dataInts = null, IEnumerable<short>? randomDataShorts = null, IEnumerable<byte>? randomDataBytes = null, IEnumerable<int>? randomDataInts = null, IEnumerable<ushort>? indices = null, bool countsFromStreams = false, bool replaceDelta = false)
    { byte[] db = (dataBytes ?? _data.DataBytes).ToArray(); short[] ds = (dataShorts ?? _data.DataShorts).ToArray(); int[] di = (dataInts ?? _data.DataInts).ToArray(); short[] rds = (randomDataShorts ?? _data.RandomDataShorts).ToArray(); byte[] rdb = (randomDataBytes ?? _data.RandomDataBytes).ToArray(); int[] rdi = (randomDataInts ?? _data.RandomDataInts).ToArray(); ushort[] ix = (indices ?? _data.Indices).ToArray(); return new XAnimBuildData(_data.Name, countsFromStreams ? checked((ushort)db.Length) : _data.DataByteCount, countsFromStreams ? checked((ushort)ds.Length) : _data.DataShortCount, countsFromStreams ? checked((ushort)di.Length) : _data.DataIntCount, countsFromStreams ? checked((ushort)rdb.Length) : _data.RandomDataByteCount, countsFromStreams ? checked((ushort)rdi.Length) : _data.RandomDataIntCount, _data.NumFrames, _data.Flags, _data.DeltaFlags, _data.BoneCounts, _data.BoneNameCount, _data.NotifyCount, _data.AssetTypeValue, _data.Pad1F, countsFromStreams ? rds.Length : _data.RandomDataShortCount, countsFromStreams ? ix.Length : _data.IndexCount, framerate ?? _data.Framerate, frequency ?? _data.Frequency, _data.Names, db, ds, di, rds, rdb, rdi, ix, _data.Notify, replaceDelta ? delta : _data.Delta); }
}

public sealed class XAnimAuthoringAdapter : AssetAuthoringAdapter<XAnimAuthoredSnapshot, XAnimDraft, XAnimBuildData>
{
    private static readonly XAnimBodyEmitter Validator = new(); public override XAssetType AssetType => XAssetType.XAnim; public override XAnimAuthoredSnapshot ImportAuthoredSnapshot(TargetZoneRowSource source) => XAnimAuthoredSnapshot.Import(source); public override XAnimDraft CreateDraft(XAnimAuthoredSnapshot snapshot) => new(snapshot.Data); public override XAnimDraft CloneDraft(XAnimDraft draft) => draft.Clone(); public override IReadOnlyList<AssetValidationIssue> ValidateDraft(XAnimDraft draft) => Validator.Validate(draft.Data).Select(value => new AssetValidationIssue(value.Path, value.Message, AssetValidationSeverity.Error)).ToArray(); public override bool SemanticallyEquals(XAnimDraft left, XAnimDraft right) => Same(left.Data, right.Data); public override XAnimBuildData ExportBuildData(XAnimDraft draft) { XAnimBuildData data = draft.Data; if (Validator.Validate(data).Count != 0) throw new InvalidOperationException("XAnim draft has validation errors and cannot produce build data."); return data; }
    private static bool Same(XAnimBuildData left, XAnimBuildData right) => left.Name == right.Name && left.DataByteCount == right.DataByteCount && left.DataShortCount == right.DataShortCount && left.DataIntCount == right.DataIntCount && left.RandomDataByteCount == right.RandomDataByteCount && left.RandomDataIntCount == right.RandomDataIntCount && left.NumFrames == right.NumFrames && left.Flags == right.Flags && left.DeltaFlags == right.DeltaFlags && left.BoneCounts.SequenceEqual(right.BoneCounts) && left.BoneNameCount == right.BoneNameCount && left.NotifyCount == right.NotifyCount && left.AssetTypeValue == right.AssetTypeValue && left.Pad1F == right.Pad1F && left.RandomDataShortCount == right.RandomDataShortCount && left.IndexCount == right.IndexCount && Bits(left.Framerate, right.Framerate) && Bits(left.Frequency, right.Frequency) && left.Names.SequenceEqual(right.Names) && left.DataBytes.SequenceEqual(right.DataBytes) && left.DataShorts.SequenceEqual(right.DataShorts) && left.DataInts.SequenceEqual(right.DataInts) && left.RandomDataShorts.SequenceEqual(right.RandomDataShorts) && left.RandomDataBytes.SequenceEqual(right.RandomDataBytes) && left.RandomDataInts.SequenceEqual(right.RandomDataInts) && left.Indices.SequenceEqual(right.Indices) && left.Notify.SequenceEqual(right.Notify) && Same(left.Delta, right.Delta);
    private static bool Same(XAnimDeltaBuildData? left, XAnimDeltaBuildData? right) => (left is null && right is null) || (left is { } a && right is { } b && Same(a.Trans, b.Trans) && Same(a.Quat2, b.Quat2) && Same(a.Quat, b.Quat));
    private static bool Same(XAnimPartTransBuildData? left, XAnimPartTransBuildData? right) => (left is null && right is null) || (left is { } a && right is { } b && a.Size == b.Size && a.SmallTrans == b.SmallTrans && a.Pad3 == b.Pad3 && Same(a.Frame0, b.Frame0) && ((a.Frames is null && b.Frames is null) || (a.Frames is { } af && b.Frames is { } bf && Same(af.Mins, bf.Mins) && Same(af.Size, bf.Size) && af.DynamicFrames.SequenceEqual(bf.DynamicFrames) && SameList(af.SmallFrames, bf.SmallFrames) && SameList(af.LargeFrames, bf.LargeFrames))));
    private static bool Same(XAnimQuat2PartBuildData? left, XAnimQuat2PartBuildData? right) => (left is null && right is null) || (left is { } a && right is { } b && a.Size == b.Size && a.Pad2 == b.Pad2 && a.Pad3 == b.Pad3 && a.Frame0 == b.Frame0 && ((a.Frames is null && b.Frames is null) || (a.Frames is { } af && b.Frames is { } bf && af.DynamicFrames.SequenceEqual(bf.DynamicFrames) && af.Frames.SequenceEqual(bf.Frames))));
    private static bool Same(XAnimQuatPartBuildData? left, XAnimQuatPartBuildData? right) => (left is null && right is null) || (left is { } a && right is { } b && a.Size == b.Size && a.Pad2 == b.Pad2 && a.Pad3 == b.Pad3 && a.Frame0 == b.Frame0 && ((a.Frames is null && b.Frames is null) || (a.Frames is { } af && b.Frames is { } bf && af.DynamicFrames.SequenceEqual(bf.DynamicFrames) && af.Frames.SequenceEqual(bf.Frames))));
    private static bool Same(Float3BuildData? left, Float3BuildData? right) => (left is null && right is null) || (left is { } a && right is { } b && Same(a, b)); private static bool Same(Float3BuildData left, Float3BuildData right) => Bits(left.X, right.X) && Bits(left.Y, right.Y) && Bits(left.Z, right.Z); private static bool SameList<T>(IReadOnlyList<T>? left, IReadOnlyList<T>? right) => left is null ? right is null : right is not null && left.SequenceEqual(right); private static bool Bits(float left, float right) => BitConverter.SingleToInt32Bits(left) == BitConverter.SingleToInt32Bits(right);
}
